set -euo pipefail; python - <<'PY'
import json, os, re
s=os.environ['ASTRA_STEP_0_BODY'].strip()
m=re.search(r'\{[\s\S]*\}',s)
if not m: raise SystemExit('NO_JSON_OBJECT')
x=json.loads(m.group(0))
a=x.get('actions')
if not isinstance(a,list) or not a: raise SystemExit('NO_ACTIONS')
allowed={'read_file','list_tree','search_text','http_get','finish'}
for i,z in enumerate(a):
    if z.get('type') not in allowed: raise SystemExit(f'UNSAFE_OR_UNKNOWN_ACTION:{i}:{z.get("type")}')
    if not isinstance(z.get('args'),dict): raise SystemExit(f'BAD_ARGS:{i}')
    if not isinstance(z.get('why'),str) or not z['why'].strip(): raise SystemExit(f'NO_RATIONALE:{i}')
print(json.dumps(x,separators=(',',':')))
print('CONSTRAINED_PLAN_VALID')
PY
